            {* Überschreibe Button-Text via TypeScript-Modul *}
<script>
    (function() {
        // Direkter Fallback (funktioniert auch ohne RequireJS)
        function directOverride() {
            const button = document.getElementById('forwardButton');
            if (!button) return;

            // Check if button was already enhanced
            if (button.classList.contains('forwardButtonEnhanced')) {
                const textElement = button.querySelector('.forwardButtonEnhanced__text');
                if (textElement) {
                    const currentText = textElement.textContent?.trim() || '';
                    const oldTexts = ['Weiterleitung bestätigen', 'Confirm redirect', 'urlshort.redirect.confirm'];

                    if (oldTexts.includes(currentText)) {
                        const lang = document.documentElement.lang || 'de';
                        const newText = lang.startsWith('de') ? 'Empfehlung ansehen' : 'View recommendation';
                        textElement.textContent = newText;
                    }
                }
                return;
            }

            const currentText = button.textContent?.trim() || button.innerText?.trim() || '';
            const oldTexts = ['Weiterleitung bestätigen', 'Confirm redirect', 'urlshort.redirect.confirm'];

            if (oldTexts.includes(currentText)) {
                const lang = document.documentElement.lang || 'de';
                const newText = lang.startsWith('de') ? 'Empfehlung ansehen' : 'View recommendation';
                button.textContent = newText;
            }
        }

        // Versuche RequireJS-Modul zu laden
        if (typeof require !== 'undefined') {
            require(["Benjaro/Urlshort/Ui/ButtonTextOverride"], (ButtonTextOverride) => {
                if (ButtonTextOverride && ButtonTextOverride.setup) {
                    ButtonTextOverride.setup();
                } else {
                    directOverride();
                }
            }, (error) => {
                directOverride();
            });
        } else {
            // Warte auf DOM
            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', directOverride);
            } else {
                directOverride();
            }
            setTimeout(directOverride, 100);
            setTimeout(directOverride, 500);
        }
    })();
</script>
